-- Frozen schema v11 used by package 25. Contains no user data.
CREATE TABLE "app_settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "library_folders" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "path" TEXT NOT NULL UNIQUE, "display_name" TEXT NULL, "is_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("is_enabled" IN (0, 1)), "is_recursive" INTEGER NOT NULL DEFAULT 1 CHECK ("is_recursive" IN (0, 1)), "last_scanned_at" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL);
CREATE TABLE "playback_events" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "operation_id" TEXT NULL, "track_id" INTEGER NOT NULL REFERENCES tracks (id) ON DELETE CASCADE, "event_type" TEXT NOT NULL, "occurred_at" INTEGER NOT NULL, "position_ms" INTEGER NULL, "duration_ms" INTEGER NULL, "wave_mode" TEXT NULL, "metadata_json" TEXT NULL);
CREATE TABLE "playlist_tracks" ("playlist_id" INTEGER NOT NULL REFERENCES playlists (id) ON DELETE CASCADE, "track_id" INTEGER NOT NULL REFERENCES tracks (id) ON DELETE CASCADE, "position" INTEGER NOT NULL, "added_at" INTEGER NOT NULL, PRIMARY KEY ("playlist_id", "track_id"));
CREATE TABLE "playlists" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "description" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL);
CREATE TABLE "track_user_state" ("track_id" INTEGER NOT NULL REFERENCES tracks (id) ON DELETE CASCADE, "is_favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favorite" IN (0, 1)), "is_hidden" INTEGER NOT NULL DEFAULT 0 CHECK ("is_hidden" IN (0, 1)), "rating" INTEGER NULL, "play_count" INTEGER NOT NULL DEFAULT 0, "complete_count" INTEGER NOT NULL DEFAULT 0, "skip_count" INTEGER NOT NULL DEFAULT 0, "last_played_at" INTEGER NULL, "last_skipped_at" INTEGER NULL, "last_completed_at" INTEGER NULL, "user_score_boost" REAL NOT NULL DEFAULT 0.0, "preferred_wave_mode" TEXT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("track_id"));
CREATE TABLE "tracks" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "library_folder_id" INTEGER NULL REFERENCES library_folders (id) ON DELETE SET NULL, "stable_id" TEXT NULL, "file_path" TEXT NOT NULL UNIQUE, "content_hash" TEXT NULL, "title" TEXT NULL, "artist" TEXT NULL, "album" TEXT NULL, "album_artist" TEXT NULL, "genre" TEXT NULL, "artwork_path" TEXT NULL, "artwork_hash" TEXT NULL, "artwork_mime_type" TEXT NULL, "custom_artwork_path" TEXT NULL, "custom_artwork_hash" TEXT NULL, "custom_artwork_mime_type" TEXT NULL, "codec" TEXT NULL, "duration_ms" INTEGER NULL, "track_number" INTEGER NULL, "disc_number" INTEGER NULL, "year" INTEGER NULL, "metadata_source" TEXT NULL, "metadata_confidence" REAL NULL, "file_size_bytes" INTEGER NULL, "modified_at" INTEGER NULL, "last_seen_at" INTEGER NULL, "is_missing" INTEGER NOT NULL DEFAULT 0 CHECK ("is_missing" IN (0, 1)), "added_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL);
CREATE INDEX idx_playback_events_track_time ON playback_events(track_id, occurred_at);
CREATE INDEX idx_playlist_tracks_playlist_position ON playlist_tracks(playlist_id, position);
CREATE INDEX idx_playlist_tracks_track ON playlist_tracks(track_id);
CREATE INDEX idx_playlists_updated ON playlists(updated_at);
CREATE INDEX idx_track_user_state_updated ON track_user_state(updated_at);
CREATE INDEX idx_tracks_last_seen ON tracks(last_seen_at);
CREATE INDEX idx_tracks_library_folder ON tracks(library_folder_id);
CREATE INDEX idx_tracks_stable_id ON tracks(stable_id) WHERE stable_id IS NOT NULL;
CREATE UNIQUE INDEX idx_playback_events_operation ON playback_events(operation_id) WHERE operation_id IS NOT NULL;
CREATE TABLE "external_track_refs" ("track_id" INTEGER NOT NULL REFERENCES tracks (id) ON DELETE CASCADE, "provider" TEXT NOT NULL, "external_id" TEXT NOT NULL, "variant_key" TEXT NOT NULL DEFAULT '', "origin" TEXT NOT NULL, "linked_at" INTEGER NOT NULL, PRIMARY KEY ("track_id", "provider", "external_id", "variant_key"));
CREATE INDEX idx_external_track_refs_identity ON external_track_refs(provider, external_id, variant_key, track_id);

CREATE TABLE "downloaded_assets" ("track_id" INTEGER NOT NULL REFERENCES tracks (id) ON DELETE CASCADE, "provider" TEXT NOT NULL, "external_id" TEXT NOT NULL, "variant_key" TEXT NOT NULL DEFAULT '', "source" TEXT NOT NULL, "publication_id" TEXT NOT NULL UNIQUE, "requested_quality" TEXT NOT NULL, "actual_quality" TEXT NOT NULL, "container" TEXT NOT NULL, "codec" TEXT NOT NULL, "file_size_bytes" INTEGER NOT NULL, "duration_ms" INTEGER NOT NULL, "content_hash" TEXT NOT NULL, "verified_at_micros" INTEGER NOT NULL, "state" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 1, PRIMARY KEY ("track_id"), FOREIGN KEY (track_id, provider, external_id, variant_key) REFERENCES external_track_refs(track_id, provider, external_id, variant_key) ON DELETE CASCADE);
CREATE INDEX idx_downloaded_assets_identity ON downloaded_assets(provider, external_id, variant_key, actual_quality, state, track_id);
PRAGMA user_version = 11;
